1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.time.temporal.ChronoUnit;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Derives an owner's {@code membershipLevel} — the numeric rank (1 to 4) returned on the owner DTO
11	 * and recorded on the create audit line.
12	 *
13	 * <p>The base level is fixed at creation from these factors:
14	 * <ul>
15	 *   <li>starts at {@code 1};</li>
16	 *   <li>adds {@code 1} when an email address is present (non-blank);</li>
17	 *   <li>adds {@code 1} when the owner's name was unique at creation, i.e. {@code namesakeCount} is
18	 *       {@code 0} (see {@link AssignNamesakeCount});</li>
19	 *   <li>adds {@code 1} when the owner is the sole member of their household at creation, i.e. no
20	 *       earlier owner shares its computed {@code householdId} (see {@link OwnerIdentity#householdIdFor});
21	 *       an owner with no household — no postcode — is always sole;</li>
22	 *   <li>capped at {@code 3} — these pre-tenure factors alone can never reach level 4.</li>
23	 * </ul>
24	 *
25	 * <p>Level {@code 4} is reserved for tenure: it is granted only when the owner's tenure — whole days
26	 * from {@code registrationDate} to today — exceeds {@code 365} days. A newly created owner has zero
27	 * tenure, so a new owner never exceeds level 3 (a new owner with an email, a {@code namesakeCount}
28	 * of 0 and a 3-member household is level 3, not 4).
29	 *
30	 * <p>Only owners created earlier (lower id) count towards the household size, so the base level stays
31	 * fixed from creation even as the household later grows.
32	 */
33	public final class MembershipLevel {
34	
35	    private static final int PRE_TENURE_MAX_LEVEL = 3;
36	
37	    private static final int MAX_LEVEL = 4;
38	
39	    private static final long TENURE_DAYS_FOR_LEVEL_4 = 365;
40	
41	    private MembershipLevel() {
42	    }
43	
44	    /** The owner's membership level, from 1 to 4. */
45	    public static int of(Owner owner, OwnerRepository ownerRepository) {
46	        int level = 1;
47	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
48	            level++;
49	        }
50	        Integer namesakeCount = owner.getNamesakeCount();
51	        if (namesakeCount != null && namesakeCount == 0) {
52	            level++;
53	        }
54	        if (isSoleHouseholdMember(owner, ownerRepository)) {
55	            level++;
56	        }
57	        level = Math.min(level, PRE_TENURE_MAX_LEVEL);
58	        if (tenureDays(owner) > TENURE_DAYS_FOR_LEVEL_4) {
59	            level++;
60	        }
61	        return Math.min(level, MAX_LEVEL);
62	    }
63	
64	    /** Whole days from the owner's {@code registrationDate} to today; {@code 0} when unknown. */
65	    private static long tenureDays(Owner owner) {
66	        LocalDate registrationDate = owner.getRegistrationDate();
67	        if (registrationDate == null) {
68	            return 0;
69	        }
70	        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
71	    }
72	
73	    /** Whether no earlier owner shares this owner's household (its computed {@code householdId}). */
74	    private static boolean isSoleHouseholdMember(Owner owner, OwnerRepository ownerRepository) {
75	        String householdId = owner.getHouseholdId();
76	        if (householdId == null || householdId.isBlank()) {
77	            return true;
78	        }
79	        Integer ownerId = owner.getId();
80	        for (Owner other : ownerRepository.findAll()) {
81	            Integer otherId = other.getId();
82	            if (otherId == null) {
83	                continue;
84	            }
85	            if (ownerId != null && (otherId.equals(ownerId) || otherId >= ownerId)) {
86	                continue; // only owners that already existed at creation count
87	            }
88	            if (householdId.equals(other.getHouseholdId())) {
89	                return false;
90	            }
91	        }
92	        return true;
93	    }
94	}
