3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns the owner's {@code namesakeCount}: the number of existing owners that already share this
11	 * owner's first name and last name, compared case-insensitively, at the moment of creation.
12	 *
13	 * <p>The new owner is not yet saved when this runs, so {@link OwnerRepository#findAll()} returns only
14	 * the pre-existing owners — the count excludes the owner being created. It is zero when the name is
15	 * unique. Runs after {@link BuildOwner} (which publishes the new owner) and before {@link SaveOwner}.
16	 */
17	public class AssignNamesakeCount {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String firstName = normalize(owner.getFirstName());
21	        String lastName = normalize(owner.getLastName());
22	        int count = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (firstName.equals(normalize(existing.getFirstName()))
25	                    && lastName.equals(normalize(existing.getLastName()))) {
26	                count++;
27	            }
28	        }
29	        owner.setNamesakeCount(count);
30	    }
31	
32	    /** Lower-cases and trims so the comparison ignores case and surrounding whitespace. */
33	    private static String normalize(String value) {
34	        if (value == null) {
35	            return "";
36	        }
37	        return value.trim().toLowerCase(Locale.ROOT);
38	    }
39	}
