4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns the owner's deterministic {@code householdId}: the first 12 upper-case hex characters of
8	 * SHA-256 over the normalized last name and postcode (see {@link OwnerIdentity#householdIdFor}).
9	 *
10	 * <p>The identifier is derived purely from {@code (lastName, postcode)}, so owners with the same last
11	 * name and postcode share it automatically, regardless of creation order and regardless of whether
12	 * they opted in with {@code sharesHousehold} — that flag now only bypasses the duplicate block (see
13	 * {@link CheckIdentityUnique}), it no longer creates the link. An owner without a postcode is not in
14	 * any household and is left with no identifier.
15	 *
16	 * <p>Runs after {@link BuildOwner} (which publishes the new owner) and before {@link SaveOwner}.
17	 */
18	public class AssignHousehold {
19	
20	    public void service(@Val Owner owner) {
21	        owner.setHouseholdId(OwnerIdentity.householdIdFor(owner.getLastName(), owner.getPostcode()));
22	    }
23	}
